// Provide a self-sizing input view as the controller's root, created here
// (earlier than viewDidLoad) so the host learns our height before the first
// layout pass. Without this, when the user switches to Lex the host briefly
// presents the extension at a default (tall, ~2/3 screen) height and only
// then snaps down to our height — the visible height "flash". A self-sizing
// UIInputView whose own height constraint exists before presentation lets
// the host size correctly on the first frame.
override func loadView() {
    let input_view = UIInputView(frame: .zero, inputViewStyle: .keyboard)
    // Honour the height constraint below via systemLayoutSizeFitting instead
    // of letting the host impose its own height. Defaults to false.
    input_view.allowsSelfSizing = true

    // Priority < required (1000) avoids conflicting with the host's own
    // required encapsulated-layout-height during transitions.
    let height_constraint = input_view.heightAnchor.constraint(
        equalToConstant: Self.keyboard_height
    )
    height_constraint.priority = UILayoutPriority(999)
    height_constraint.isActive = true

    self.view = input_view
}

override func viewDidLoad() {
    super.viewDidLoad()

    self.keyboard_view.translatesAutoresizingMaskIntoConstraints = false
    self.keyboard_view.delegate = self
    self.view.addSubview(self.keyboard_view)

    NSLayoutConstraint.activate([
        self.keyboard_view.leadingAnchor.constraint(equalTo: self.view.leadingAnchor),
        self.keyboard_view.trailingAnchor.constraint(equalTo: self.view.trailingAnchor),
        self.keyboard_view.topAnchor.constraint(equalTo: self.view.topAnchor),
        self.keyboard_view.bottomAnchor.constraint(equalTo: self.view.bottomAnchor),
    ])

    self.refresh_traits(force: true)
}

